import numpy as np
from scipy import stats
from sklearn.cluster import AgglomerativeClustering

MAX_DRIVERS = 5

def design(feats):
    # Calculate t-statistics for each feature
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            continue  # Skip clinical features for now

        x_col = feats.x[:, feats.column(fid)]
        y = feats.y

        # Separate data by outcome
        x0 = x_col[y == 0]
        x1 = x_col[y == 1]

        # Perform Welch's t-test
        if len(x0) > 0 and len(x1) > 0:
            t_stat, p_val = stats.ttest_ind(x0, x1, equal_var=False)
            if p_val < 0.05:
                sig_features.append((fid, t_stat, p_val))

    # Sort by effect size (absolute t-statistic)
    sig_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # If no significant features, return empty design
    if not sig_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Get top features for correlation analysis
    top_features = [fid for fid, _, _ in sig_features[:20]]  # Top 20 for correlation

    # Compute correlation matrix
    if len(top_features) < 2:
        # Not enough features to form meaningful correlations
        module_features = [top_features[0]] if top_features else []
        # Simple loading based on mean difference
        if module_features:
            fid = module_features[0]
            col_idx = feats.column(fid)
            x_col = feats.x[:, col_idx]
            y = feats.y
            x0 = x_col[y == 0]
            x1 = x_col[y == 1]
            if len(x0) > 0 and len(x1) > 0:
                mean_diff = np.mean(x1) - np.mean(x0)
                loadings = {fid: mean_diff}
            else:
                loadings = {}
            return Design(
                drivers=(fid,) if module_features else (),
                columns=tuple(module_features),
                products=(),
                loadings=loadings
            )
        else:
            return Design(drivers=(), columns=(), products=(), loadings={})

    # Get correlation matrix for top features
    corr_matrix = np.zeros((len(top_features), len(top_features)))
    for i, fid1 in enumerate(top_features):
        for j, fid2 in enumerate(top_features):
            if i == j:
                corr_matrix[i, j] = 1.0
            else:
                idx1 = feats.column(fid1)
                idx2 = feats.column(fid2)
                corr_matrix[i, j] = np.corrcoef(feats.x[:, idx1], feats.x[:, idx2])[0, 1]

    # Cluster highly correlated features (|r| >= 0.6)
    mask = np.abs(corr_matrix) >= 0.6
    np.fill_diagonal(mask, False)

    # Find connected components using clustering
    if np.sum(mask) > 0:
        # Use hierarchical clustering
        clustering = AgglomerativeClustering(
            n_clusters=None,
            distance_threshold=1-0.6,
            linkage='complete',
            connectivity=mask
        )
        try:
            clusters = clustering.fit_predict(np.eye(len(top_features)))

            # Select largest cluster as module
            unique_clusters, counts = np.unique(clusters, return_counts=True)
            if len(unique_clusters) > 0:
                main_cluster = unique_clusters[np.argmax(counts)]
                module_features = [top_features[i] for i in range(len(top_features)) if clusters[i] == main_cluster]
            else:
                module_features = top_features[:1]
        except:
            module_features = top_features[:1]
    else:
        module_features = top_features[:1]

    # Calculate weighted score using first principal component
    if len(module_features) > 1:
        module_indices = [feats.column(fid) for fid in module_features]
        module_data = feats.x[:, module_indices]
        # Center the data
        module_data_centered = module_data - np.mean(module_data, axis=0)
        # SVD to get principal component
        u, s, v = np.linalg.svd(module_data_centered, full_matrices=False)
        loadings = dict(zip(module_features, v[0]))
    elif len(module_features) == 1:
        # For single feature, use standardized value directly
        fid = module_features[0]
        loadings = {fid: 1.0}
    else:
        loadings = {}

    # Return design with module members and their loadings
    return Design(
        drivers=(module_features[0],) if module_features else (),
        columns=tuple(module_features),
        products=(),
        loadings=loadings
    )

